# R golden fixtures for gaply_core's crosstabs and chi-square as an analysis
# (Research OS, Phase 8X-1, decisions 575 to 577, capability
# stats.analyze.crosstabs).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_xtab_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only: the stats package (chisq.test, fisher.test, pchisq).
# Written with R 4.6.1, whose version the files' headers record.
#
# Writes, next to this script:
#   * data_*.csv: one synthetic dataset per case (a two-line '#' header, then
#     `id,r,c`), each READ BACK as Gaply reads levels: read.csv with
#     strip.white = TRUE, both columns as character, "" and "NaN" as missing
#     (two of Gaply's missing tokens, stats_verify::is_missing), numeric
#     levels plain integers only, so R's text is Gaply's level code;
#   * counts_*.csv: for the larger cases, a table of counts (`r,c,n`) that
#     the test and this script both expand to rows the same way: each pair in
#     the file's order, repeated n times;
#   * cases.tsv: each case's file, its rows' and columns' headers, and its
#     missing codes;
#   * expected.tsv: R's answer for every case, one number per row (case, key,
#     value), the value as %.17g; a level's label as text; for a refusal,
#     the code and its parameters.
#
# A cell is a NUMBER, as Gaply reads it, when it parses as a finite number;
# a number equal to a missing code is left out, and a text cell ("Inf" here)
# never matches a code. A row is left out once, by the first reason found:
# the rows' column empty, then coded, then the columns' column empty, then
# coded. The levels are the included rows' distinct values in code-point
# order, sort(method = "radix"), whatever the locale: Gaply's order
# (decision 78).
#
# Where each number comes from:
#   * the counts: table(); the expected counts, chisq.test()$expected; the
#     Pearson residuals, $residuals; the adjusted standardized residuals,
#     $stdres; the proportions, the counts over their totals;
#   * Pearson's chi-square: sum((O - E)^2 / E) with O - E taken in whole
#     numbers, (O n - r c) / n, which is exact where chisq.test's own O - E
#     loses digits; checked against chisq.test(correct = FALSE)$statistic,
#     stopping on a difference over 1e-9 relative, except near_independent,
#     where chisq.test's own statistic is rounding noise; its p, pchisq(X2,
#     df, lower.tail = FALSE), which is chisq.test's p.value;
#   * the likelihood ratio: 2 sum(O log1p((O - E) / E)) over O > 0, O - E in
#     whole numbers as above; its p from pchisq. No base R function gives it,
#     so THE SAME FORMULA IS WRITTEN TWICE, here and in gaply_core;
#   * the continuity-corrected chi-square: chisq.test(correct = TRUE), 2 x 2;
#   * Fisher's exact test: fisher.test()'s p.value for two.sided, less and
#     greater, 2 x 2;
#   * phi, 2 x 2: (n11 n22 - n12 n21) / sqrt(r1 r2 c1 c2), checked against
#     sqrt(X2 / n) in size; larger: sqrt(X2 / n); Cramer's V, sqrt(X2 / (n
#     (min(r, c) - 1))); the contingency coefficient, sqrt(X2 / (X2 + n)).
#     No base R function gives them: THE SAME FORMULAS ARE WRITTEN TWICE,
#     on R's X2;
#   * the expected counts' facts: how many r c < 5 n, in whole numbers, and
#     min(E).
#
# Synthetic data only. No manuscript or data of anyone's is read.

here <- local({
  a <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f)) dirname(normalizePath(f)) else getwd()
})
setwd(here)

HEADER <- c(
  "# Synthetic data for gaply_core's crosstabs R golden fixtures (Research OS, Phase 8X-1).",
  "# Generated by /usr/local/bin/Rscript make_xtab_fixtures.R (do not edit by hand)."
)
fmt <- function(x) if (is.character(x)) x else if (is.na(x)) "NA" else sprintf("%.17g", x)

cases <- character()
expected <- character()
emit <- function(case, key, value) {
  expected <<- c(expected, paste(case, key, fmt(value), sep = "\t"))
}
add_case <- function(case, file, rows, columns, codes) {
  cases <<- c(cases, paste(case, file, rows, columns,
                           if (length(codes)) paste(codes, collapse = " ") else "-", sep = "\t"))
}

# Each pair (r[i], c[j]) repeated counts[i, j] times, row by row: the
# expansion the test makes from a counts file.
expand <- function(counts, rl, cl) {
  r <- character(); cc <- character()
  for (i in seq_len(nrow(counts))) for (j in seq_len(ncol(counts))) {
    r <- c(r, rep(rl[i], counts[i, j])); cc <- c(cc, rep(cl[j], counts[i, j]))
  }
  data.frame(r = r, c = cc, stringsAsFactors = FALSE)
}

# A data file: the rows in a fixed shuffled order, written, then read back.
write_data <- function(name, r, cc) {
  n <- length(r)
  o <- order((seq_len(n) * 7919) %% 10007, seq_len(n))
  r <- r[o]; cc <- cc[o]
  path <- paste0("data_", name, ".csv")
  rs <- ifelse(is.na(r), "", r); cs <- ifelse(is.na(cc), "", cc)
  writeLines(c(HEADER, "id,r,c", paste(seq_len(n), rs, cs, sep = ",")), path, useBytes = TRUE)
  read.csv(path, comment.char = "#", na.strings = c("", "NaN"), strip.white = TRUE,
           colClasses = c("integer", "character", "character"), encoding = "UTF-8")
}

write_counts <- function(name, counts, rl, cl) {
  path <- paste0("counts_", name, ".csv")
  lines <- character()
  for (i in seq_len(nrow(counts))) for (j in seq_len(ncol(counts))) {
    lines <- c(lines, paste(rl[i], cl[j], counts[i, j], sep = ","))
  }
  writeLines(c(HEADER, "r,c,n", lines), path, useBytes = TRUE)
  expand(counts, rl, cl)
}

coded <- function(x, codes) {
  num <- suppressWarnings(as.numeric(x))
  !is.na(x) & !is.na(num) & is.finite(num) & num %in% codes
}

radix_levels <- function(x) sort(unique(x), method = "radix")

analyse <- function(case, d, codes = numeric(), refusal = FALSE) {
  missing_row <- is.na(d$r)
  code_rows <- !missing_row & coded(d$r, codes)
  rest <- !missing_row & !code_rows
  missing_column <- rest & is.na(d$c)
  code_columns <- rest & !is.na(d$c) & coded(d$c, codes)
  keep <- rest & !is.na(d$c) & !code_columns
  rl <- radix_levels(d$r[keep]); cl <- radix_levels(d$c[keep])
  if (refusal) {
    for (w in list(list("rows", length(rl)), list("columns", length(cl)))) {
      k <- w[[2]]
      if (k < 2) { emit(case, "refused", "stats.xtab.too_few_levels")
                   emit(case, "refused.column", w[[1]]); emit(case, "refused.count", k); return(invisible()) }
      if (k > 50) { emit(case, "refused", "stats.xtab.too_many_levels")
                    emit(case, "refused.column", w[[1]]); emit(case, "refused.count", k)
                    emit(case, "refused.limit", 50); return(invisible()) }
    }
    stop(case, ": a refusal case that R does not refuse")
  }
  stopifnot(length(rl) >= 2, length(cl) >= 2, length(rl) <= 50, length(cl) <= 50)
  emit(case, "excluded.missing_row", sum(missing_row))
  emit(case, "excluded.missing_code.rows", sum(code_rows))
  emit(case, "excluded.missing_column", sum(missing_column))
  emit(case, "excluded.missing_code.columns", sum(code_columns))
  O <- unclass(table(factor(d$r[keep], levels = rl), factor(d$c[keep], levels = cl)))
  O <- matrix(as.numeric(O), nrow = length(rl))
  n <- sum(O); r <- nrow(O); k <- ncol(O)
  rs <- rowSums(O); cs <- colSums(O)
  ct <- suppressWarnings(chisq.test(O, correct = FALSE))
  E <- ct$expected
  D <- (O * n - outer(rs, cs)) / n
  X2 <- sum(D^2 / E)
  df <- (r - 1) * (k - 1)
  if (case != "near_independent") {
    stopifnot(abs(X2 - unname(ct$statistic)) <= 1e-9 * X2)
  }
  pos <- O > 0
  G2 <- 2 * sum(O[pos] * log1p(D[pos] / E[pos]))
  emit(case, "n", n); emit(case, "rows", r); emit(case, "columns", k)
  for (i in seq_len(r)) emit(case, sprintf("row_level.%d", i - 1), rl[i])
  for (j in seq_len(k)) emit(case, sprintf("column_level.%d", j - 1), cl[j])
  for (i in seq_len(r)) emit(case, sprintf("row_total.%d", i - 1), rs[i])
  for (j in seq_len(k)) emit(case, sprintf("column_total.%d", j - 1), cs[j])
  for (i in seq_len(r)) for (j in seq_len(k)) {
    key <- function(s) sprintf("cell.%d.%d.%s", i - 1, j - 1, s)
    emit(case, key("observed"), O[i, j])
    emit(case, key("expected"), E[i, j])
    emit(case, key("row_proportion"), O[i, j] / rs[i])
    emit(case, key("column_proportion"), O[i, j] / cs[j])
    emit(case, key("total_proportion"), O[i, j] / n)
    emit(case, key("residual"), D[i, j])
    emit(case, key("pearson_residual"), ct$residuals[i, j])
    emit(case, key("adjusted_residual"), ct$stdres[i, j])
  }
  emit(case, "pearson.statistic", X2); emit(case, "pearson.df", df)
  emit(case, "pearson.p", pchisq(X2, df, lower.tail = FALSE))
  emit(case, "likelihood_ratio.statistic", G2); emit(case, "likelihood_ratio.df", df)
  emit(case, "likelihood_ratio.p", pchisq(G2, df, lower.tail = FALSE))
  if (r == 2 && k == 2) {
    y <- suppressWarnings(chisq.test(O, correct = TRUE))
    emit(case, "continuity_corrected.statistic", unname(y$statistic))
    emit(case, "continuity_corrected.df", unname(y$parameter))
    emit(case, "continuity_corrected.p", y$p.value)
    for (alt in c("two.sided", "less", "greater")) {
      emit(case, paste0("fisher.", sub(".", "_", alt, fixed = TRUE)),
           fisher.test(O, alternative = alt)$p.value)
    }
    phi <- (O[1, 1] * O[2, 2] - O[1, 2] * O[2, 1]) / sqrt(rs[1] * rs[2] * cs[1] * cs[2])
    if (case != "near_independent") stopifnot(abs(abs(phi) - sqrt(X2 / n)) <= 1e-9 * abs(phi))
  } else {
    phi <- sqrt(X2 / n)
  }
  emit(case, "phi", unname(phi))
  emit(case, "cramers_v", sqrt(X2 / (n * (min(r, k) - 1))))
  emit(case, "contingency_coefficient", sqrt(X2 / (X2 + n)))
  emit(case, "expected_below_five", sum(outer(rs, cs) < 5 * n))
  emit(case, "cell_count", r * k)
  emit(case, "smallest_expected", min(E))
  emit(case, "note.expected_below_five", as.numeric(any(outer(rs, cs) < 5 * n)))
}

refuse <- function(case, code, params) {
  emit(case, "refused", code)
  for (p in names(params)) emit(case, paste0("refused.", p), params[[p]])
}

m <- function(...) matrix(c(...), nrow = 2, byrow = TRUE)

# ---- 2 x 2 tables --------------------------------------------------------
x <- expand(m(12, 5, 7, 9), c("no", "yes"), c("a", "b"))
d <- write_data("t2x2_small", x$r, x$c); add_case("t2x2_small", "data_t2x2_small.csv", "r", "c", c())
analyse("t2x2_small", d)

x <- expand(m(0, 8, 6, 3), c("off", "on"), c("left", "right"))
d <- write_data("t2x2_zero", x$r, x$c); add_case("t2x2_zero", "data_t2x2_zero.csv", "r", "c", c())
analyse("t2x2_zero", d)

d <- write_counts("t2x2_large", m(25300, 24700, 24600, 25400), c("A", "B"), c("X", "Y"))
add_case("t2x2_large", "counts_t2x2_large.csv", "r", "c", c()); analyse("t2x2_large", d)

# n11 n22 - n12 n21 = 1 at n = 99,988: O - E is 1 / n in every cell, and X2
# and G2 are near 1.6e-14, where a double's sum of terms is noise: summed as
# gaply_core sums it, G2 is -5.5e-12 before its clamp at 0 (measured
# 9 Nov 2026), so this is the case where the clamp acts.
d <- write_counts("near_independent", m(24997, 24996, 24998, 24997), c("A", "B"), c("X", "Y"))
add_case("near_independent", "counts_near_independent.csv", "r", "c", c())
analyse("near_independent", d)

# ---- larger tables -------------------------------------------------------
x <- expand(matrix(c(10, 4, 7, 3, 12, 6), nrow = 2, byrow = TRUE), c("f", "m"), c("low", "mid", "high"))
d <- write_data("t2x3", x$r, x$c); add_case("t2x3", "data_t2x3.csv", "r", "c", c()); analyse("t2x3", d)

x <- expand(matrix(c(8, 3, 5, 9, 2, 11, 6, 4, 7, 5, 10, 3), nrow = 3, byrow = TRUE),
            c("g1", "g2", "g3"), c("w", "x", "y", "z"))
d <- write_data("t3x4", x$r, x$c); add_case("t3x4", "data_t3x4.csv", "r", "c", c()); analyse("t3x4", d)

c5 <- outer(0:4, 0:4, function(i, j) 3 + ((i * 3 + j * 5) %% 11) * 2)
d <- write_counts("t5x5", c5, paste0("r", 1:5), paste0("c", 1:5))
add_case("t5x5", "counts_t5x5.csv", "r", "c", c()); analyse("t5x5", d)

# 50 x 50, 2,401 df: the rows' levels the numbers 1 to 50 (code-point order
# 1, 10, 11, ..., 19, 2, 20, ...), the columns' k00 to k49. Every ninth
# diagonal of i + 2j raised by 4, so X2 is near 2,590 and p near 0.004: the
# chi-square at 2,401 df away from both ends.
c50 <- outer(0:49, 0:49, function(i, j) 1 + ((i * 7 + j * 13) %% 5) + 4 * ((i + 2 * j) %% 9 == 0))
d <- write_counts("t50x50", c50, as.character(1:50), sprintf("k%02d", 0:49))
add_case("t50x50", "counts_t50x50.csv", "r", "c", c()); analyse("t50x50", d)

d <- write_counts("low_expected", matrix(c(1, 0, 3, 2, 5, 1, 0, 2, 6), nrow = 3, byrow = TRUE),
                  c("p", "q", "s"), c("u", "v", "w"))
add_case("low_expected", "counts_low_expected.csv", "r", "c", c()); analyse("low_expected", d)

# ---- the levels' order ---------------------------------------------------
# Code-point order is not alphabetical: upper case first, then lower case,
# then letters outside ASCII (Ä U+00C4, É U+00C9, Ö U+00D6, é U+00E9).
x <- expand(matrix(c(4, 2, 3, 1, 5, 2, 2, 6, 1, 3, 2, 4, 3, 1, 5, 2, 4, 3), nrow = 6, byrow = TRUE),
            c("Zebra", "apple", "Äpfel", "éclair", "Ölung", "banana"), c("ja", "nein", "vielleicht"))
d <- write_data("codepoint_text", x$r, x$c)
add_case("codepoint_text", "data_codepoint_text.csv", "r", "c", c()); analyse("codepoint_text", d)

# 2 and 10 as numbers: code-point order puts 10 first, so phi's sign and
# Fisher's directions are those of the table with 10 on the first row.
x <- expand(m(9, 3, 4, 10), c("2", "10"), c("0", "1"))
d <- write_data("numeric_2_10", x$r, x$c)
add_case("numeric_2_10", "data_numeric_2_10.csv", "r", "c", c()); analyse("numeric_2_10", d)

x <- expand(matrix(c(5, 2, 3, 6, 4, 4), nrow = 3, byrow = TRUE), c("-2", "-1", "1"), c("a", "b"))
d <- write_data("numeric_negative", x$r, x$c)
add_case("numeric_negative", "data_numeric_negative.csv", "r", "c", c()); analyse("numeric_negative", d)

# ---- missing codes and empty cells --------------------------------------
# -9 and 99 are codes. The rows' column holds -9 (2 rows) and 99 (3); the
# columns' column holds 99 (4 rows, one of them on a row already left out by
# its rows' cell, which counts once, for the rows' column) and -9 (1). "Inf"
# is a text level, never a code; "NaN" is a missing token.
r <- c(rep("1", 9), rep("2", 8), rep("3", 7), "-9", "-9", "99", "99", "99", "Inf", "Inf", "Inf", "NaN")
cc <- c(rep(c("x", "y", "x"), 3), rep(c("y", "x"), 4), rep(c("x", "y", "y"), 2), "x",
        "x", "99", "x", "y", "99", "x", "y", "Inf", "y")
cc[1] <- "99"; cc[10] <- "99"; cc[11] <- "-9"; cc[12] <- "99"
d <- write_data("codes_both", r, cc)
add_case("codes_both", "data_codes_both.csv", "r", "c", c(-9, 99)); analyse("codes_both", d, c(-9, 99))

r <- c(rep("u", 8), rep("v", 7), NA, NA, NA, "u", "v", NA)
cc <- c(rep(c("p", "q"), 4), rep(c("q", "p"), 3), "q", "p", NA, "q", NA, NA, NA)
d <- write_data("empty_both", r, cc)
add_case("empty_both", "data_empty_both.csv", "r", "c", c()); analyse("empty_both", d)

# ---- refusals, one for each check that data decides ----------------------
x <- expand(m(3, 2, 4, 1), c("a", "b"), c("x", "y"))
d <- write_data("refuse_codes", x$r, x$c)
add_case("refuse_code_not_finite", "data_refuse_codes.csv", "r", "c", c("NaN"))
refuse("refuse_code_not_finite", "stats.xtab.missing_code_not_finite", list(index = 0))
add_case("refuse_codes_out_of_order", "data_refuse_codes.csv", "r", "c", c(9, 1))
refuse("refuse_codes_out_of_order", "stats.xtab.missing_codes_out_of_order", list(index = 1))
add_case("refuse_code_repeated", "data_refuse_codes.csv", "r", "c", c(9, 9))
refuse("refuse_code_repeated", "stats.xtab.missing_code_repeated", list(index = 1))
add_case("refuse_unknown_column", "data_refuse_codes.csv", "nosuch", "c", c())
refuse("refuse_unknown_column", "stats.xtab.unknown_column", list(column = "rows"))
add_case("refuse_same_column", "data_refuse_codes.csv", "r", "r", c())
refuse("refuse_same_column", "stats.xtab.same_column", list())

d <- write_data("refuse_one_level", rep("only", 6), c("x", "y", "x", "y", "x", "x"))
add_case("refuse_one_level", "data_refuse_one_level.csv", "r", "c", c())
analyse("refuse_one_level", d, refusal = TRUE)

# Two levels in the columns' column, one of them the code 7, so one among the
# included rows.
d <- write_data("refuse_coded_level", c("a", "b", "a", "b", "a", "b"), c("7", "7", "z", "z", "7", "z"))
add_case("refuse_coded_level", "data_refuse_coded_level.csv", "r", "c", c(7))
analyse("refuse_coded_level", d, c(7), refusal = TRUE)

d <- write_data("refuse_51_levels", sprintf("L%02d", 0:101 %% 51), rep(c("x", "y"), 51))
add_case("refuse_51_levels", "data_refuse_51_levels.csv", "r", "c", c())
analyse("refuse_51_levels", d, refusal = TRUE)

d <- write_data("refuse_no_rows", c(NA, NA, "a", "b"), c("x", "y", NA, NA))
add_case("refuse_no_rows", "data_refuse_no_rows.csv", "r", "c", c())
analyse("refuse_no_rows", d, refusal = TRUE)

stamp <- c("# written by: /usr/local/bin/Rscript make_xtab_fixtures.R",
           sprintf("# %s, base R stats only", R.version.string))
writeLines(c(stamp, "case\tfile\trows\tcolumns\tmissing_codes", cases), "cases.tsv", useBytes = TRUE)
writeLines(c(stamp, "case\tkey\tvalue", expected), "expected.tsv", useBytes = TRUE)
cat(sprintf("%d cases, %d expected values\n", length(cases), length(expected)))
